create extension if not exists "pgcrypto";
create type public.app_role as enum ('admin','sales_director','sales_manager','sales_rep','sales_operations','viewer');
create type public.opportunity_stage as enum ('qualification','discovery','proposal','negotiation','closed_won','closed_lost');
create type public.approval_status as enum ('draft','pending','approved','rejected','cancelled');
create table public.profiles (id uuid primary key references auth.users on delete cascade, full_name text not null, role public.app_role not null default 'sales_rep', job_title text, created_at timestamptz not null default now());
create table public.customers (id uuid primary key default gen_random_uuid(), name text not null, industry text, account_owner uuid references public.profiles, created_at timestamptz not null default now());
create table public.partners (id uuid primary key default gen_random_uuid(), name text not null, partner_type text not null check (partner_type in ('dealer','reseller','system_integrator')), contact_name text, created_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(), sku text unique, name text not null, category text, active boolean not null default true, created_at timestamptz not null default now());
create table public.opportunities (id uuid primary key default gen_random_uuid(), name text not null, customer_id uuid not null references public.customers, partner_id uuid references public.partners, owner_id uuid references public.profiles, stage public.opportunity_stage not null default 'qualification', amount numeric(14,2), probability smallint check (probability between 0 and 100), expected_close_date date, created_at timestamptz not null default now());
create table public.activities (id uuid primary key default gen_random_uuid(), opportunity_id uuid references public.opportunities on delete cascade, customer_id uuid references public.customers on delete cascade, owner_id uuid references public.profiles, title text not null, due_at timestamptz, completed_at timestamptz, created_at timestamptz not null default now(), check (opportunity_id is not null or customer_id is not null));
create table public.documents (id uuid primary key default gen_random_uuid(), opportunity_id uuid references public.opportunities on delete cascade, customer_id uuid references public.customers on delete cascade, storage_path text not null unique, file_name text not null, uploaded_by uuid references public.profiles, created_at timestamptz not null default now());
create table public.approvals (id uuid primary key default gen_random_uuid(), opportunity_id uuid not null references public.opportunities on delete cascade, requested_by uuid references public.profiles, approver_id uuid references public.profiles, status public.approval_status not null default 'draft', request_type text not null, justification text, decided_at timestamptz, created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.customers enable row level security; alter table public.partners enable row level security; alter table public.products enable row level security; alter table public.opportunities enable row level security; alter table public.activities enable row level security; alter table public.documents enable row level security; alter table public.approvals enable row level security;
create policy "authenticated read" on public.customers for select to authenticated using (true); create policy "authenticated read" on public.partners for select to authenticated using (true); create policy "authenticated read" on public.products for select to authenticated using (true); create policy "authenticated read" on public.opportunities for select to authenticated using (true); create policy "authenticated read" on public.activities for select to authenticated using (true); create policy "authenticated read" on public.documents for select to authenticated using (true); create policy "authenticated read" on public.approvals for select to authenticated using (true);
